name="NoBrand VLESS REALITY ${id}"
command="${NOBRAND_XRAY_BIN}"
command_args="run -c ${NOBRAND_REALITY_CONFIG_DIR}/${id}/config.json"
export XRAY_LOCATION_ASSET="${NOBRAND_XRAY_ASSET_DIR}"
command_background="yes"
